&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_vsdjv4j4qn3d&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkanı Mahmut Arıkan&amp;rsquo;ın Grup Toplantısı Konuşması&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_aziy7qlm29wa&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;AVRUPA&amp;rsquo;DAN SELAM GETİRDİM&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;S&amp;ouml;zlerimin hemen başında, &amp;uuml;zerimde olan selamları paylaşmak istiyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hafta sonu Avrupa&amp;rsquo;daydık. Avrupa&amp;rsquo;da yaşayan vatandaşlarımızla bir araya geldik, &amp;ouml;zlem giderdik. Hepsinin sizlere &amp;ccedil;ok&amp;ccedil;a selamları var.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ben buradan -bir kez daha- Avrupa teşkilatlarımıza, &amp;ouml;zverili &amp;ccedil;alışmaları i&amp;ccedil;in teşekk&amp;uuml;r ediyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Nasıl T&amp;uuml;rkiye&amp;rsquo;yi karış karış geziyor, 86 milyon insanımızın dertlerini ve taleplerini dinleyip notlarımızı alıyorsak; aynı şekilde yurt dışında yaşayan vatandaşlarımızın da taleplerini dinleyip notlarımızı alıyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_hrfifijdslmb&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;MECLİS &amp;Ouml;NERGEMİZ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Avrupa&amp;rsquo;da yaşayan vatandaşlarımızın talepleri var. Hem de bunlar &amp;ccedil;ok haklı talepler.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidar mensuplarının gayet iyi bildiği talepler bunlar.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;ok değil ge&amp;ccedil;tiğimiz hafta, 23 Ekim g&amp;uuml;n&amp;uuml; grup olarak bir meclis &amp;ouml;nergesi verdik. &amp;ldquo;Yurtdışında yaşayan vatandaşlarımızın sorunlarını ve &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;ouml;nerilerini b&amp;uuml;t&amp;uuml;nc&amp;uuml;l bir yaklaşımla ele alalım&amp;rdquo; dedik.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yine, yeniden, yıllardır her &amp;ouml;nergede olduğu gibi; AK Parti ve MHP oylarıyla reddedildi. Ardından, &amp;ccedil;ok değil, 7 g&amp;uuml;n sonra Avrupa&amp;rsquo;da yaşayan vatandaşlarımızla bir araya geldik.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;G&amp;ouml;rd&amp;uuml;k ki; bizim burada konuşalım dediğimiz, iktidarın konuşmayalım dediği her şey orada vatandaşımızın haklı talebleri!&amp;nbsp;&amp;nbsp;Vatandaşlarımız d&amp;ouml;rt g&amp;ouml;zle TBMM&amp;rsquo;de atılacak adımları bekliyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_12ua4oszqp95&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;YURT DIŞINDA YAŞAYAN VATANDAŞLARIMIZIN HAKLI TALEPLERİ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yurt dışında yaşayan kardeşlerimiz;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Mecliste layıkıyla temsil edilmek istiyor,&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;k&lt;span style=&quot;color:black&quot;&gt;amu hizmetlerine erişimin &amp;ouml;n&amp;uuml;ndeki b&amp;uuml;rokratik engellerin kalkmasını istiyor,&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;konomik hayatı d&amp;uuml;zene sokacak d&amp;uuml;zenlemeleri bekliyor&lt;/span&gt;.&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Eğitim ve diploma konularında karışıklığın son bulmasını istiyor,&lt;/span&gt;&amp;nbsp;g&lt;span style=&quot;color:black&quot;&gt;&amp;uuml;mr&amp;uuml;k ve yol &amp;ccedil;ilesi bitsin istiyor&lt;/span&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bunlar, birtakım d&amp;uuml;zenlemeler ile &amp;ccedil;&amp;ouml;z&amp;uuml;lebilecek meseleler. Ancak bırakın d&amp;uuml;zenlemeyi, iktidar cenahı bunların mecliste konuşulmasını bile istemiyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz, bu meseleleri bir siyaset malzemesi olarak değil, vatandaşlarımızın g&amp;uuml;nl&amp;uuml;k hayatını kolaylaştıracak birer insani gereklilik olarak g&amp;ouml;r&amp;uuml;yoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Her platformda olduğu gibi, bu konuda da b&amp;uuml;t&amp;uuml;n engellemelere rağmen yapıcı bir tutum sergilemeye kararlıyız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yurtdışında yaşayan vatandaşlarımızın hak ettikleri temsil, hizmet ve saygıya kavuşmaları i&amp;ccedil;in &amp;ccedil;alışmaya; &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;ouml;nerilerimizi muhataplarıyla paylaşmaya devam edeceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_6sp01kklr9gf&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;ALIŞAMAYAN GAZETECİLER GER&amp;Ccedil;EĞİ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;D&amp;uuml;n bizim i&amp;ccedil;in &amp;ouml;zel bir g&amp;uuml;nd&amp;uuml;. Hepinizin malumu; T&amp;uuml;rkiye&amp;rsquo;de medya, tarihinin en zor d&amp;ouml;nemlerinden birini yaşıyor. &amp;Ouml;zellikle son d&amp;ouml;nemde yerel ve ulusal bazda bir&amp;ccedil;ok gazete ve televizyon kapandı veya kayyum atandı, -bizim tespit edebildiğimiz kadarıyla- son bir ayda 500&amp;rsquo;den fazla gazeteci arkadaşımız işsiz kaldı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biliyorsunuz bir &amp;ldquo;&amp;ccedil;alışan gazeteciler g&amp;uuml;n&amp;uuml;&amp;rdquo; vardı. Artık T&amp;uuml;rkiye&amp;rsquo;de bir de &amp;ldquo;&amp;ccedil;alışamayan gazeteciler ger&amp;ccedil;eği&amp;rdquo; var.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;D&amp;uuml;n gazeteci arkadaşlarımızla ve meslek &amp;ouml;rg&amp;uuml;tlerinin temsilcileriyle bir araya geldik, bu konuyu konuştuk. Katılan, katkı sunan t&amp;uuml;m medya mensuplarımıza teşekk&amp;uuml;r ediyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_cuu3z4qpwj6k&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;İKTİDAR MEDYAYI İKİ YOLLA KONTROL ALTINA ALMAYA &amp;Ccedil;ALIŞIYOR&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidar, medyayı iki yolla kontrol altına almaya &amp;ccedil;alışıyor:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Birincisi, ekonomik baskılarla. Nedir bunlar: Reklam kesintileridir, cezalardır, adaletsiz reklam dağıtımıdır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İkincisi, siyasi baskılarla. Sans&amp;uuml;rle, g&amp;ouml;zdağı ile, hedef g&amp;ouml;sterme ile.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_s4euqqgq59vg&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;REKLAM DAĞILIMINDAKİ ADALETSİZLİK&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ekonomik baskı ile ilgili, &amp;ccedil;arpıcı bir rakamı paylaşmak istiyorum:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;a name=&quot;z89vpp97rewf&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yaptığımız bir &amp;ccedil;alışmaya g&amp;ouml;re: Ocak 2025 ile Ekim 2025 arasındaki, 10 aylık d&amp;ouml;nemde, iktidarın kontrol&amp;uuml;nde olan TMSF b&amp;uuml;nyesindeki şirketlerden, iktidara destek veren televizyon kanallarına verilen reklam s&amp;uuml;resi 14 milyon 810 bin 298 saniye. Bu inanılmaz bir rakam. Peki bunun karşılığında,&amp;nbsp;&amp;nbsp;birileri tarafından muhalif diye adlandırılan,&amp;nbsp;&amp;nbsp;televizyon kanallarına verilen reklam s&amp;uuml;resi ne kadar? Sıfır! Bu durum &amp;ccedil;ok b&amp;uuml;y&amp;uuml;k bir haksızlıktır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_yu35py3lbkan&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;GAZETECİLİK SU&amp;Ccedil; GİBİ G&amp;Ouml;STERİLİYOR&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Geldiğimiz noktada;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye&amp;rsquo;de Gazetecilik faaliyetleri bir su&amp;ccedil; gibi g&amp;ouml;sterilmeye başlandı&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Şunu unutmayalım; Ger&amp;ccedil;eği yazmak cezalandırıldığında, yalan &amp;ouml;d&amp;uuml;llendirilmeye&amp;nbsp;başlar. T&amp;uuml;rkiye&amp;rsquo;de yaşanan tam olarak budur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

