&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_fbdegimey02v&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;GAZZE&amp;rsquo;DE DEĞİŞEN BİR ŞEY OLMADI&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hepimizin bildiği gibi 10 Ekim&amp;rsquo;de ter&amp;ouml;rist İsrail ile Hamas arasında bir ateşkes imzalandı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu ateşkeste ABD, Katar, Mısır ve T&amp;uuml;rkiye garant&amp;ouml;r &amp;uuml;lke olarak yer aldı.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu nasıl bir ateşkes, bu garant&amp;ouml;rler nasıl garant&amp;ouml;rse; 10 Ekim&amp;#39;den bug&amp;uuml;ne ter&amp;ouml;rist İsrail 200&amp;rsquo;den daha fazla ateşkes ihlali yaptı, y&amp;uuml;zlerce mazlumu katletti. Yine bu s&amp;uuml;rede yardım konvoylarının, ila&amp;ccedil; ve tıbbi malzemelerin girişi yeterli olmadı; hastaların &amp;ccedil;ıkışı i&amp;ccedil;in Refah Sınır Kapısı a&amp;ccedil;ılmadı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Neticede; değişen bir şey olmadı! Akan kan, d&amp;ouml;k&amp;uuml;len g&amp;ouml;zyaşı bitmedi. Bitecek gibi de g&amp;ouml;z&amp;uuml;km&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_uekfst52njqk&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;HER HAFTA NEYE TEŞEKK&amp;Uuml;R EDİLİYOR?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hal b&amp;ouml;yleyken, her hafta yapılan a&amp;ccedil;ıklamalarda &amp;ldquo;Sayın Trump&amp;rsquo;a teşekk&amp;uuml;r ederiz&amp;rdquo; c&amp;uuml;mlelerini duymaya devam ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu neyin teşekk&amp;uuml;r&amp;uuml;?&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;İşletilmeyen garant&amp;ouml;r sorumlulukları i&amp;ccedil;in mi teşekk&amp;uuml;r ediyorsunuz?&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Yoksa gelecek yeni ticaret anlaşmaları i&amp;ccedil;in mi teşekk&amp;uuml;r ediyorsunuz?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_vm76hve8vihy&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;BARRACK M&amp;Uuml;NNECİM OLMADIĞINA G&amp;Ouml;RE!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;ABD&amp;rsquo;nin Ankara B&amp;uuml;y&amp;uuml;kel&amp;ccedil;isi Tom Barrack&amp;rsquo;ın Bahreyn&amp;rsquo;deki a&amp;ccedil;ıklamaları ş&amp;uuml;pheleri tam da bu konu &amp;uuml;zerine &amp;ccedil;ekti.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Diyor ki; &amp;ldquo;T&amp;uuml;rkiye ve İsrail birbiriyle savaşmayacak&amp;rdquo; hatta &amp;ldquo;&amp;ccedil;ok uzak olmayan gelecekte bir ticaret anlaşması imzalanabilir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;ok uzak olmayan geleceği bırakın, biz &amp;ldquo;&amp;ccedil;ok uzak olmayan bir ge&amp;ccedil;mişte de&amp;rdquo; ticari ilişkileri g&amp;ouml;rd&amp;uuml;k.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ateşkes g&amp;ouml;r&amp;uuml;şmeleri yapılırken bu k&amp;uuml;rs&amp;uuml;den uyarıda bulunduk! &amp;ldquo;Anlaşma yapıldı diye,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;bitirdik&amp;rdquo; denilen ama &amp;ouml;rt&amp;uuml;k şekilde devam eden ticaret artarak devam etmemeli&amp;rdquo;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;dedik.&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Gelinen noktada, T&amp;uuml;rkiye yine&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;İsrail&amp;rsquo;in can damarı olan &amp;ldquo;Ticaret imtihanını&amp;rdquo; veremeyecek gibi g&amp;ouml;z&amp;uuml;k&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Barrack&amp;rsquo;ın a&amp;ccedil;ıklamaları bununla da sınırlı değil!&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;&amp;ldquo;Hazar Denizi&amp;#39;nden Akdeniz&amp;#39;e kadar bir hizalanma g&amp;ouml;receksiniz.&amp;rdquo; diyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Birincisi; &amp;ldquo;s&amp;ouml;m&amp;uuml;rge valisi&amp;rdquo; edasıyla yapılan konuşmalara, iktidarın en b&amp;uuml;y&amp;uuml;k tepkiyi koyması gerekir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İkincisi; Barrack m&amp;uuml;neccim olmadığına g&amp;ouml;re&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;B&amp;uuml;t&amp;uuml;n bunları aslında işletilen planın bir aşaması olarak s&amp;ouml;yl&amp;uuml;yor. Hep s&amp;ouml;yledik yine s&amp;ouml;yl&amp;uuml;yoruz. Bu planın adı: B&amp;uuml;y&amp;uuml;k Ortadoğu Projesidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye; ne eş başkan, ne garant&amp;ouml;r, hi&amp;ccedil;bir unvanla bu projeye &amp;ldquo;dahil&amp;rdquo; olmamalıdır! Bilakis T&amp;uuml;rkiye bu plana, bu gidişata muhakkak surette &amp;ldquo;m&amp;uuml;dahil&amp;rdquo; olmalıdır!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_qkdenq3i8qrj&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;SUDAN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir g&amp;ouml;z&amp;uuml;m&amp;uuml;z Gazze&amp;rsquo;de, bir g&amp;ouml;z&amp;uuml;m&amp;uuml;z neredeyse aynı hikayenin yaşandığı Sudan&amp;rsquo;da! Gelen g&amp;ouml;r&amp;uuml;nt&amp;uuml;leri hepimiz g&amp;ouml;rd&amp;uuml;k. Bug&amp;uuml;n Sudan&amp;rsquo;da yaşananlar, basit bir &amp;ldquo;i&amp;ccedil; savaş&amp;rdquo; tanımını &amp;ccedil;oktan aşıyor. Peki neden? Neden bu vahşet? İ&amp;ccedil; karışıklık gibi lanse edilse de; emperyal odakların g&amp;ouml;z diktiği altın, petrol ve nadir toprak elementleri. Sudan&amp;rsquo;ın en b&amp;uuml;y&amp;uuml;k zenginliği iken en b&amp;uuml;y&amp;uuml;k imtihanı olmuş durumda.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_iyq2vmc9gnfg&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;KARDEŞ KANINDAN KİMSEYE FAYDA GELMEZ!&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Şu unutulmamalı; yery&amp;uuml;z&amp;uuml;nde kimseye kardeş kanından fayda gelmemiştir. Kaybedenler, o toprak &amp;uuml;zerinde yaşayanlar, Kazananlar, emperyalizm ve Siyonizm olmuştur. Sudan&amp;rsquo;da da oynanan oyun bu al&amp;ccedil;ak stratejinin tekrarıdır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_o65mium8az8h&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;GER&amp;Ccedil;EK D&amp;Uuml;ŞMAN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ger&amp;ccedil;ek d&amp;uuml;şman Emperyalizmdir! Ger&amp;ccedil;ek d&amp;uuml;şman Siyonizm&amp;rsquo;dir.&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Ve Hi&amp;ccedil;bir g&amp;uuml;ndem,&lt;/span&gt;&amp;nbsp;h&lt;span style=&quot;color:black&quot;&gt;i&amp;ccedil;bir plan&lt;/span&gt;, h&lt;span style=&quot;color:black&quot;&gt;i&amp;ccedil;bir ateşkes,&lt;/span&gt;h&lt;span style=&quot;color:black&quot;&gt;i&amp;ccedil;bir garant&amp;ouml;r,&lt;/span&gt;&amp;nbsp;Gazze&amp;rsquo;yi unutturmamalıdır! Sudan&amp;rsquo;ı unutturmamalıdır! İsrail&amp;rsquo;i umutlandırmamalıdır! Ve Amerika&amp;rsquo;yı cesaretlendirmemelidir!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_p8gg07oob3an&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;MİLLİ DAYANIŞMA, KARDEŞLİK VE DEMOKRASİ KOMİSYONU&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli Arkadaşlar,&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir yılı aşkın bir s&amp;uuml;redir&amp;nbsp;&amp;nbsp;t&amp;uuml;m kaygılarımıza rağmen, katkı vermeye &amp;ccedil;alıştığımız bir s&amp;uuml;re&amp;ccedil; var. Bizim de i&amp;ccedil;erisinde yer aldığımız bir komisyon kuruldu. Milli Dayanışma, Kardeşlik ve Demokrasi Komisyonu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Evet!&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Artan eşitsizlikler karşısında dayanışmaya ihtiyacımız vardı.&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Farklı kimlikler ve k&amp;uuml;lt&amp;uuml;rler olarak kardeşliğe ihtiyacımız vardı.&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;oğunluğun azınlığa tahakk&amp;uuml;m&amp;uuml;ne değil &amp;ccedil;oğulcu bir demokrasiye ihtiyacımız vardı.&lt;/span&gt;Komisyonun ismi tam da &amp;uuml;lkemizin ihtiya&amp;ccedil;larına binaen verilmiş oldu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;K&amp;uuml;rt meselesi başta olmak &amp;uuml;zere t&amp;uuml;m toplumsal sorunların TBMM&amp;rsquo;de tartışılıp,&amp;nbsp;&amp;nbsp;yine Meclis zemininde &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;ouml;nerilerinin konuşulabilmesi kuşkusuz olumlu bir durumdur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ancak yapılan komisyon toplantılarında iktidar cenahından bizimle paylaşılan&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;umudumuzu artıran yeni bir bilgi yoktur,&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;ne hedeflendiğini g&amp;ouml;steren somut bir plan yoktur,&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;varılmak istenen noktaya dair bir yol haritası yoktur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_20vig0xjor6c&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;ESAMESİ OKUNMADI!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu s&amp;uuml;re&amp;ccedil;te;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Anayasa Mahkemesi&amp;rsquo;nin kararlarına rağmen,&lt;/span&gt;&amp;nbsp;Avrupa İnsan Hakları Mahkemesi&amp;rsquo;nin kararlarına rağmen tutuklu ve h&amp;uuml;k&amp;uuml;ml&amp;uuml;lerle ile ilgili bir gelişme olmadı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sefalete mahk&amp;ucirc;m edilen,&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;grev hakları ellerinden alınan, emek&amp;ccedil;ilerin, e&lt;span style=&quot;color:black&quot;&gt;meklilikten sonra ucuz iş g&amp;uuml;c&amp;uuml; olarak &amp;ccedil;alışmak zorunda kalan emeklileri&lt;/span&gt;n, b&lt;span style=&quot;color:black&quot;&gt;ir taban maaşı olmayan &amp;ouml;zel e&lt;/span&gt;ğitim &amp;ouml;ğretmenlerinin, a&lt;span style=&quot;color:black&quot;&gt;dalet arayan KHK&lt;/span&gt;&amp;rsquo;lıların, tutuklu askeri okul &amp;ouml;ğrencilerinin, k&lt;span style=&quot;color:black&quot;&gt;&amp;uuml;rs&amp;uuml;lerine kavuşmak isteyen barış akademisyenlerinin&lt;/span&gt;, c&lt;span style=&quot;color:black&quot;&gt;an g&amp;uuml;venliğinden endişe eden kad&lt;/span&gt;ınların, k&lt;span style=&quot;color:black&quot;&gt;okarcadan, dondan ve kuraklıktan etkilen &amp;ccedil;ift&amp;ccedil;ini&lt;/span&gt;n, ş&lt;span style=&quot;color:black&quot;&gt;ap hastalığıyla ilgili sesini bir t&amp;uuml;rl&amp;uuml; duyuramayan hayvan &amp;uuml;re&lt;/span&gt;ticisin esamesi bile okunmadı, sesleri yine duyulmadı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz; &amp;ldquo;Milli Dayanışma, Kardeşlik, Demokrasi&amp;rdquo; derken, bu kesimlerin sorunlarının dile gelmesini, &amp;ccedil;&amp;ouml;z&amp;uuml;mlerin konuşulmasını bekliyorduk.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Fakat ge&amp;ccedil;en bir yıl i&amp;ccedil;inde ne bu meseleler samimiyetle ele alındı ne de s&amp;uuml;rece dair hukuki bir zemin oluşturuldu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir taraftan hukuki boyutu tartışmalı bir s&amp;uuml;re&amp;ccedil; yaşanırken&amp;nbsp;&amp;nbsp;diğer taraftan&amp;nbsp;&amp;nbsp;Anayasamızın ve uluslararası hukukun gereklerine rağmen tehir edilen adaletin tanıkları olduk.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hem Selahattin Demirtaş&amp;#39;ın, hem Can Atalay&amp;#39;ın hem adalet arayan askeri okul &amp;ouml;ğrencilerilerinin hem Osman Kavala&amp;#39;nın hem de KHK&amp;rsquo;lıların mağduriyetlerinin giderilmesi bir l&amp;uuml;tuf değil hukukun gereğidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_2yo3gu76vfnl&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;SU&amp;Ccedil;A S&amp;Uuml;R&amp;Uuml;KLENEN &amp;Ccedil;OCUKLAR&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;B&amp;uuml;t&amp;uuml;n bu tartışmaların, ideolojik kısır d&amp;ouml;ng&amp;uuml;lerin ve y&amp;uuml;zeysel yaklaşımların g&amp;ouml;lgesinde asıl sorunlar sessiz sessiz b&amp;uuml;y&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İşsizlik, yoksulluk, eğitimsizlik ve umutsuzluk; gen&amp;ccedil;lerimizin, &amp;ccedil;ocuklarımızın kaderine d&amp;ouml;n&amp;uuml;şm&amp;uuml;ş durumda.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu &amp;ccedil;arpıklık y&amp;uuml;z&amp;uuml;nden, &amp;ldquo;su&amp;ccedil;a s&amp;uuml;r&amp;uuml;klenen &amp;ccedil;ocuklar&amp;rdquo; gibi kavramları tartışmak zorunda kalıyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Son yıllarda artan &amp;ccedil;ete olayları, huzur ve emniyeti tehdit etmekle beraber ya &amp;ccedil;ocuklarımızı elimizden alıyor ya da su&amp;ccedil;a s&amp;uuml;r&amp;uuml;kl&amp;uuml;yor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kalem tutması gereken eller, silah tutuyor&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;, o&lt;span style=&quot;color:black&quot;&gt;kula gitmesi gereken &amp;ccedil;ocuklar, cezaevine d&amp;uuml;ş&amp;uuml;yor,&lt;/span&gt;&amp;nbsp;s&lt;span style=&quot;color:black&quot;&gt;ınava hazırlanması gerekenler evlatlarımız, mahkemelere hazırlanıyorlar.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_en42m04lmng8&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;OK SORU VAR!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sorulacak &amp;ccedil;ok sorumuz var! &amp;Ccedil;&amp;uuml;nk&amp;uuml; ciğerimiz yanıyor ciğerimiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Şimdi ben; bir şekilde evladı elinden kayıp gitmiş g&amp;ouml;z&amp;uuml; yaşlı aileler adına buradan soruyorum!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;K&amp;uuml;rs&amp;uuml;lerde g&amp;uuml;venlikten s&amp;ouml;z eden h&amp;uuml;k&amp;uuml;met yetkilileri,&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;mahalle aralarında &amp;quot;sessiz h&amp;uuml;k&amp;uuml;m s&amp;uuml;ren&amp;quot; &amp;ccedil;etelerden haberdar mısınız?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu &amp;uuml;lkenin sokaklarında, mahalle aralarında,&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;hatta dijital platformlarda &amp;ouml;rg&amp;uuml;tlenen ka&amp;ccedil; yapı var, biliyormusunuz?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Daha doğrusu, bilmek istiyormusunuz?&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;İ&amp;ccedil;işleri Bakanlığı sadece operasyon sayısını değil, neden bu operasyonlara ihtiya&amp;ccedil; duyulduğunu da a&amp;ccedil;ıklamak zorundadır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ka&amp;ccedil; &amp;ccedil;ocuk su&amp;ccedil;a s&amp;uuml;r&amp;uuml;klendi değil; neden s&amp;uuml;r&amp;uuml;klendi? Ka&amp;ccedil; &amp;ccedil;ete var değil; nasıl b&amp;uuml;y&amp;uuml;d&amp;uuml;?&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Ka&amp;ccedil; kişi &amp;ldquo;adam &amp;ouml;ld&amp;uuml;r&amp;uuml;l&amp;uuml;r&amp;rdquo; diye ilan veriyor değil; nasıl bu c&amp;uuml;reti buluyor?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sorular ağır, cevaplar belki daha da ağır olacak. Ama asıl tehlike, bu sorular hi&amp;ccedil; sorulmadığında başlıyor!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ben şimdi size en can alıcı, soruyu s&amp;ouml;yleyeceğim! Yoksulluk, ekonomik eşitsizlik ve gelecek kaygısı bu işin neresinde? Hakikaten! T&amp;uuml;rkiye ekonomisi nasıl y&amp;ouml;netiliyor?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:left&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_eupaa4sb15vs&quot;&gt;&lt;/a&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Uuml;RETMEYEN T&amp;Uuml;RKİYE&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Cevabı belli, T&amp;uuml;rkiye ekonomisi y&amp;ouml;netilemiyor! Binlerce yıldır &amp;ldquo;&amp;uuml;retici&amp;rdquo; olmakla bilinen topraklar, bug&amp;uuml;n neredeyse tamamen t&amp;uuml;ketici konumuna d&amp;uuml;şt&amp;uuml;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İktidarın y&amp;uuml;r&amp;uuml;tt&amp;uuml;ğ&amp;uuml; yanlış politikalar sonucunda esnaf batarken, &amp;ccedil;ift&amp;ccedil;i, k&amp;uuml;&amp;ccedil;&amp;uuml;k işletmeci batarken; sanayi kuruluşları adeta can &amp;ccedil;ekişiyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bakınız bu konu ile ilgili &amp;ccedil;arpıcı bir rakam vereceğim.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

